<?php
require __DIR__.'/db.php';$pageTitle='Enrollments';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='create'){$st=$pdo->prepare('INSERT INTO enrollments(student_id,course_id,semester_no,academic_year,enrolled_on) VALUES(?,?,?,?,?)');$st->execute([$_POST['student_id'],$_POST['course_id'],$_POST['semester_no'],$_POST['academic_year'],$_POST['enrolled_on']]);$msg='Enrollment created.';}elseif($a==='delete'){$st=$pdo->prepare('DELETE FROM enrollments WHERE enrollment_id=?');$st->execute([$_POST['enrollment_id']]);$msg='Enrollment deleted.';}}catch(Throwable $e){$msg='Error: '.$e->getMessage();}}
$students=$pdo->query("SELECT student_id,CONCAT(first_name,' ',last_name) name,enrollment_no FROM students WHERE status='Active' ORDER BY first_name")->fetchAll();$courses=$pdo->query('SELECT course_id,course_code,course_name FROM courses ORDER BY course_code')->fetchAll();$rows=$pdo->query('SELECT e.*,s.enrollment_no,CONCAT(s.first_name," ",s.last_name) student_name,c.course_code FROM enrollments e JOIN students s ON s.student_id=e.student_id JOIN courses c ON c.course_id=e.course_id ORDER BY e.enrollment_id DESC')->fetchAll();include __DIR__.'/partials/header.php';
?>
<div class="hero"><div><h1>Enrollments</h1><p>Many-to-many relationship between students and courses.</p></div></div><?php if($msg): ?><div class="notice success"><?=htmlspecialchars($msg)?></div><?php endif; ?><div class="form-card"><form method="post"><input type="hidden" name="action" value="create"><div class="form-grid"><div class="field"><label>Student</label><select name="student_id"><?php foreach($students as $s): ?><option value="<?=$s['student_id']?>"><?=htmlspecialchars($s['enrollment_no'].' - '.$s['name'])?></option><?php endforeach; ?></select></div><div class="field"><label>Course</label><select name="course_id"><?php foreach($courses as $c): ?><option value="<?=$c['course_id']?>"><?=htmlspecialchars($c['course_code'].' - '.$c['course_name'])?></option><?php endforeach; ?></select></div><div class="field"><label>Semester</label><input type="number" name="semester_no" min="1" max="8" required></div><div class="field"><label>Academic Year</label><input name="academic_year" value="2026-27" required></div><div class="field"><label>Enrolled On</label><input type="date" name="enrolled_on" value="<?=date('Y-m-d')?>"></div><div class="field"><button class="btn">Create Enrollment</button></div></div></form></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Student</th><th>Course</th><th>Semester</th><th>Academic Year</th><th>Date</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['enrollment_id']?></td><td><?=htmlspecialchars($r['enrollment_no'].' - '.$r['student_name'])?></td><td><?=$r['course_code']?></td><td><?=$r['semester_no']?></td><td><?=$r['academic_year']?></td><td><?=$r['enrolled_on']?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="enrollment_id" value="<?=$r['enrollment_id']?>"><button class="btn small danger">Delete</button></form></td></tr><?php endforeach; ?></table></div><?php include __DIR__.'/partials/footer.php'; ?>
